+            [],
+        )
+        .unwrap();
+    assert!(db.child_tool_job("parent", "launch").unwrap().is_none());
+    db.conn
+        .lock()
+        .unwrap()
+        .execute(
+            "UPDATE events SET payload=?1 WHERE kind='subagent_launch'",
+            [&launch],
+        )
+        .unwrap();
+    db.conn
